// === Tab: Moon ===
class Moon {
	constructor(x, y, r, c) {
		this.x = x;
		this.y = y;
		this.r = r;
		this.c = c;
		this.na = 0.5; // noise average, will be corrected, when no overlapping
		this.lines = [];
		this.mn = random(-0.2, 0.2); // magic number, little offseting
	}

	calcNoiseAverage() {
		let na = 0;
		const num = 100;
		for (let a = 0; a < TAU; a += TAU/num) na += this.getN(a);
		na /= num;
		this.na = na;
	}

	getN(a) {
		const nx = this.x + sin(a) * this.r;
		const ny = this.y + cos(a) * this.r;
		const n = noise(2*nx/S, 2*ny/S);
		return n;
	}

	accN(n, mid = 0.5, f = 2) {
		// n = ((n - 0.5) * f + f/2) / f;
		n = mid - f * (mid - n);
		n = constrain(n, 0.1, 0.9)
		return n;
	}

	overlaps(others, pt = null) {
		if (!pt) pt = {x: this.x, y: this.y, r: this.r};
		for (const other of others) {
			if (other === this) continue;
			if (dist(pt.x, pt.y, other.x, other.y) < pt.r + other.r) return true;
		}
		return false;
	}

	nearbyLines(pt) {
		for (const ln of this.lines) {
			if (dist(ln.x, ln.y, pt.x, pt.y) < DST * SCL) return true;
		}
		return false;
	}

	draw(others) {
		for (let i = 0; i < 10; i++) {
			const a = random(TAU);
			var n = this.accN(this.getN(a), this.na);
			const r = this.r + (RMAX-this.r) * n * random()**12;
			const x = this.x + sin(a) * r;
			const y = this.y + cos(a) * r;

			let nb = 0;
			// dont draw when to many neigboars, out of screen, or overlaps with moon or lines center
			if (nb > 5 || x < 0 || x > width || y < 0 || y > height) continue;
			if (this.overlaps(others, {x, y, r: 1})) if (random()<0.9) continue;
			if (this.nearbyLines({x, y})) continue;

			// draw nebula
			stroke(this.c);
			// point(x, y);
			const ns = noise(x/S + this.mn, y/width + this.mn);
			const an = ns - 0.5;
			const vec2 = createVector(x - S/2, y - S/2).rotate(HALF_PI*0 + 2*an).normalize().mult(SCL);
			const vec = createVector(S/2, 0).rotate(TAU*an).normalize().mult(LEN * SCL);
			const x1 = x + vec.y;
			const y1 = y - vec.x;
			const x2 = x - vec.y;
			const y2 = y + vec.x;
			line(x1, y1, x2, y2);
			this.lines.push({x1, y1, x2, y2, x, y});

			// console.log(`${R1}, ${R2}, ${r}, ${n}`)
		}
	}
}

