function saveSVG(svg_name = "epi.svg.txt") {
	let svgStr = `<svg width="${width}" height="${height}" xmlns="http://www.w3.org/2000/svg">\n`;

	const prec = 2;
	for (const moon of moons) {
		svgStr += `<g stroke="${moon.c}">\n`;
		for (const ln of moon.lines) {
			svgStr += `<line x1="${nf(ln.x1,0,prec)}" y1="${nf(ln.y1,0,prec)}" x2="${nf(ln.x2,0,prec)}" y2="${nf(ln.y2,0,prec)}" />\n`;
		}
		svgStr += `</g>\n`;
	}
	svgStr += `</svg>`;

	// console.log(svgStr)
	save(svgStr.split("\n"), svg_name)
}

