var PENS = ["silver", "darkred", "purple"]; // ["silver", "darkorange", "darkred", "navy", "purple"];
var SCL = 3, LEN = 1.5, DST = 5;

var S, RMAX; // size canvas, inner and max outer radius, noise average
var seed, moons;

function setup() {
	createCanvas(210*SCL, 297*SCL);
	S=max(windowWidth, windowHeight);
	describe("pixels forming nebula behind moon");
	// frameRate(5);
	RMAX = ~~(S * 0.8);
	background(4, 4, 12);
	stroke("silver");
	strokeWeight(2);
	noFill();

	seed = ~~random(1234567);
	noiseSeed(seed);
	randomSeed(seed);
	console.log(`seed: ${seed}`);

	moons = [];
	for (let i = 0; i < PENS.length; i++) {
		var x = random(0.2, 0.8) * width;
		var y = random(0.2, 0.8) * height;
		var r = random(0.1, 0.2) * max(width, height);
		const c = PENS[i]; // random(PENS);
		const moon = new Moon(x, y, r, c);
		if (!moon.overlaps(moons)) {
			moon.calcNoiseAverage();
			moons.push(moon);
		}
	} 
}

function draw() {
	for (const moon of moons) {
		moon.draw(moons);
	}
}

function doubleClicked() {
	setup();
}

